"""Proposed required own-A102 tests; parent must install and gate the exact source first."""
from copy import deepcopy
from dataclasses import replace
import os
from unittest.mock import patch
import pytest
from .resource_task_checks import OWNERS, HOMES, fixture, own, path_for, native_trace, capture
STAGE = os.environ['A102_RESOURCE_INTEGRATION_STAGE']
assert STAGE in ('baseline', 'installed')
ROOT_HOMES = tuple((h for h, _, _ in OWNERS if not h.startswith('scientific_process/')))

@pytest.fixture
def actual(request, tmp_path):
    with fixture(request.param, tmp_path / 'actual') as value:
        yield value

def descriptors(v, profile=None):
    bindings = [own(home.replace('/', '.') + '.episode').ResourceEpisode(v.services, resource_adapters=(v.native,), contract_information_profile=profile) for home in HOMES]
    return (bindings, [binding.as_record() for binding in bindings])

def compose(v, records, **overrides):
    operational = own('a102_resources').A102ResourceCredit(v.native)
    role_bindings = {role: {'definition': operational.as_record(), 'project': operational} for _, _, role in OWNERS}
    arguments = dict(store=v.store, journal=v.journal, execution_backend=None, descriptors=records, job_episodes=None, resource_estimator=None, role_credit_bindings=role_bindings, tool_registry=v.tools)
    arguments.update(overrides)
    with patch.object(own('a102_resources'), 'now', lambda: '2026-11-12T00:00:00+00:00'):
        result = own('episode_composition').compose_episode_bindings(v.services, **arguments)
    return (result, operational)

@pytest.mark.parametrize('actual,profile', [('resource_work_submission', False), ('resource_work_submission', True), ('resource_work_submission/api_resource_work_execution', False), ('resource_work_submission/api_resource_work_execution', True), ('resource_work_submission/local_resource_work_execution', False), ('resource_work_submission/local_resource_work_execution', True), ('resource_work_submission/hpc_resource_work_execution', False), ('resource_work_submission/hpc_resource_work_execution', True), ('resource_result_acquisition', False), ('resource_result_acquisition', True), ('scientific_process/resource_work_submission', False), ('scientific_process/resource_work_submission', True), ('scientific_process/resource_work_submission/api_resource_work_execution', False), ('scientific_process/resource_work_submission/api_resource_work_execution', True), ('scientific_process/resource_work_submission/local_resource_work_execution', False), ('scientific_process/resource_work_submission/local_resource_work_execution', True), ('scientific_process/resource_work_submission/hpc_resource_work_execution', False), ('scientific_process/resource_work_submission/hpc_resource_work_execution', True), ('scientific_process/resource_result_acquisition', False), ('scientific_process/resource_result_acquisition', True)], indirect=['actual'], ids=['home=resource_work_submission;profile=false', 'home=resource_work_submission;profile=true', 'home=resource_work_submission/api_resource_work_execution;profile=false', 'home=resource_work_submission/api_resource_work_execution;profile=true', 'home=resource_work_submission/local_resource_work_execution;profile=false', 'home=resource_work_submission/local_resource_work_execution;profile=true', 'home=resource_work_submission/hpc_resource_work_execution;profile=false', 'home=resource_work_submission/hpc_resource_work_execution;profile=true', 'home=resource_result_acquisition;profile=false', 'home=resource_result_acquisition;profile=true', 'home=scientific_process/resource_work_submission;profile=false', 'home=scientific_process/resource_work_submission;profile=true', 'home=scientific_process/resource_work_submission/api_resource_work_execution;profile=false', 'home=scientific_process/resource_work_submission/api_resource_work_execution;profile=true', 'home=scientific_process/resource_work_submission/local_resource_work_execution;profile=false', 'home=scientific_process/resource_work_submission/local_resource_work_execution;profile=true', 'home=scientific_process/resource_work_submission/hpc_resource_work_execution;profile=false', 'home=scientific_process/resource_work_submission/hpc_resource_work_execution;profile=true', 'home=scientific_process/resource_result_acquisition;profile=false', 'home=scientific_process/resource_result_acquisition;profile=true'])
def test_private_resource_roundtrip_preserves_exact_original_operands(actual, profile):
    v = actual
    configured = own('composition_information').CONTRACT_INFORMATION_PROFILE if profile else None
    original, records = descriptors(v, configured)
    if STAGE == 'baseline':
        with pytest.raises(own('method_loop.durable').DurableExecutionError) as raised:
            compose(v, records)
        assert raised.value.failure['code'] == 'unavailable_binding'
        assert raised.value.failure['affected_refs'] == ['resource_work_submission']
        return
    result, projector = compose(v, records)
    assert len(result.bindings) == 10 and result.progress_provider is None
    assert [binding.as_record() for binding in result.bindings] == records
    assert [type(binding) for binding in result.bindings] == [type(binding) for binding in original]
    assert [binding.binding_path for binding in result.bindings] == list(HOMES)
    restored = [next(iter(binding.adapters.values())) for binding in result.bindings]
    assert len({id(adapter) for adapter in restored}) == 1
    for adapter in restored:
        assert type(adapter) is own('a102_resources').A102ResourceAdapter
        assert adapter.tools is v.tools and adapter.store is v.store and (adapter.run_id == v.journal.run_id)
        assert adapter.as_record() == v.native.as_record()
    assert all((binding.services is v.services for binding in result.bindings))
    assert all((value is projector for value in result.role_credit_projectors.values()))
    assert len(result.resource_capabilities) == 1
    assert result.resource_capabilities[0]['resource_id'] == v.native.resource_id
    assert result.resource_capabilities[0]['observed_at'] == '2026-11-12T00:00:00+00:00'

