def test_reopened_adapter_preserves_original_saved_job_and_receiving_outcomes(actual, status, retryable):
    v = actual
    if STAGE == 'installed':
        _, records = descriptors(v)
        result, _ = compose(v, records)
        v.native = next(iter(result.bindings[0].adapters.values()))
    result = native_trace(v, status, retryable)
    assert result['native_science_executed'] is False
    if status == 'completed':
        assert result['credit']['handoff_count'] == 1
        assert result['credit']['collected_native_comparison_count'] == 0
        assert result['delivery'] == result['outer_delivery']
CONFLICTS = (('resource_work_submission', 'execution_job_submission', 'launch'), ('resource_result_acquisition', 'execution_result_acquisition', 'results'), ('scientific_process/resource_work_submission', 'scientific_process/execution_job_submission', 'launch'), ('scientific_process/resource_result_acquisition', 'scientific_process/execution_result_acquisition', 'results'))

@pytest.mark.parametrize('resource_home,execution_home,role,reverse', [('resource_work_submission', 'execution_job_submission', 'launch', False), ('resource_work_submission', 'execution_job_submission', 'launch', True), ('resource_result_acquisition', 'execution_result_acquisition', 'results', False), ('resource_result_acquisition', 'execution_result_acquisition', 'results', True), ('scientific_process/resource_work_submission', 'scientific_process/execution_job_submission', 'launch', False), ('scientific_process/resource_work_submission', 'scientific_process/execution_job_submission', 'launch', True), ('scientific_process/resource_result_acquisition', 'scientific_process/execution_result_acquisition', 'results', False), ('scientific_process/resource_result_acquisition', 'scientific_process/execution_result_acquisition', 'results', True)], indirect=[], ids=['home=resource_work_submission;reverse=false', 'home=resource_work_submission;reverse=true', 'home=resource_result_acquisition;reverse=false', 'home=resource_result_acquisition;reverse=true', 'home=scientific_process/resource_work_submission;reverse=false', 'home=scientific_process/resource_work_submission;reverse=true', 'home=scientific_process/resource_result_acquisition;reverse=false', 'home=scientific_process/resource_result_acquisition;reverse=true'])
def test_actual_conflicting_factory_families_never_select_a_same_parent_winner(tmp_path, resource_home, execution_home, role, reverse):
    with fixture(resource_home, tmp_path / 'actual') as v:
        directory = v.output / 'workflow'
        workspace = v.output / 'selected-local'
        workspace.mkdir()
        execution = own(execution_home.replace('/', '.') + '.episode').ExecutionEpisode(v.services, store=v.store, directory=directory, run_id=v.journal.run_id, tool_registry=v.tools, resources={'selected-local': {'kind': 'local', 'workspace': str(workspace), 'policy': {'memory_bytes': 5368709120, 'scratch_bytes': 4294967296}}}, initial_information={}, handoff_unit=2.5, acquired_record_unit=3.5, log_window_bytes=5, log_roles=['stdout'])
        resource = own(resource_home.replace('/', '.') + '.episode').ResourceEpisode(v.services, resource_adapters=(v.native,))
        records = [resource.as_record(), execution.as_record()]
        if reverse:
            records.reverse()
        with pytest.raises(own('method_loop.durable').DurableExecutionError) as raised:
            compose(v, records, directory=directory)
        if STAGE == 'baseline':
            assert raised.value.failure['code'] == 'unavailable_binding'
        else:
            assert raised.value.failure['code'] == 'identity_conflict'
            assert raised.value.failure['affected_refs'] == ['episode_bindings']
            assert type(raised.value.__cause__) is ValueError
            assert str(raised.value.__cause__) == 'duplicate_episode_role:' + role
